import json
import re
from difflib import SequenceMatcher

import pandas as pd
import pdfplumber

VENDORS_PATH = '/root/vendors.xlsx'
POS_PATH = '/root/purchase_orders.csv'
INVOICES_PATH = '/root/invoices.pdf'
OUTPUT_PATH = '/root/fraud_report.json'

vendors = pd.read_excel(VENDORS_PATH)

# Normalize columns
vendors = vendors.rename(columns={c: c.strip().lower() for c in vendors.columns})


def normalize_name(name: str) -> str:
    if name is None:
        return ''
    s = name.lower()
    s = re.sub(r'[.,]', '', s)
    # normalize common variants
    s = re.sub(r'\blimited\b', 'ltd', s)
    s = re.sub(r'\bltd\b', 'ltd', s)
    s = re.sub(r'[^a-z0-9 ]', ' ', s)
    s = re.sub(r'\s+', ' ', s)
    return s.strip()


vendor_records = []
for _, row in vendors.iterrows():
    name = str(row['name'])
    vendor_records.append({
        'id': str(row['id']),
        'name': name,
        'norm': normalize_name(name),
        'iban': str(row['iban']).strip().upper().replace(' ', ''),
    })

norm_to_vendor = {}
for v in vendor_records:
    norm_to_vendor.setdefault(v['norm'], []).append(v)


def match_vendor(name: str):
    if not name:
        return None, 0.0
    norm = normalize_name(name)
    if norm in norm_to_vendor:
        # Prefer exact normalized match
        return norm_to_vendor[norm][0], 1.0
    best = None
    best_ratio = 0.0
    for v in vendor_records:
        ratio = SequenceMatcher(None, norm, v['norm']).ratio()
        if ratio > best_ratio:
            best_ratio = ratio
            best = v
    if best_ratio >= 0.9:
        return best, best_ratio
    return None, best_ratio


pos = pd.read_csv(POS_PATH)
pos = pos.rename(columns={c: c.strip().lower() for c in pos.columns})

po_map = {}
for _, row in pos.iterrows():
    po_number = str(row['po_number']).strip()
    po_map[po_number] = {
        'vendor_id': str(row['vendor_id']).strip(),
        'amount': float(row['amount']),
    }


def parse_invoice(text: str):
    vendor_name = None
    amount = None
    iban = None
    po_number = None

    m = re.search(r'^From:\s*(.+)$', text, re.MULTILINE)
    if m:
        vendor_name = m.group(1).strip()

    m = re.search(r'^Total\s*\$?([0-9]+(?:\.[0-9]{2})?)$', text, re.MULTILINE)
    if m:
        amount = float(m.group(1))

    m = re.search(r'^Payment IBAN:\s*(\S+)$', text, re.MULTILINE)
    if m:
        iban = m.group(1).strip()

    m = re.search(r'^PO Number:\s*(\S+)$', text, re.MULTILINE)
    if m:
        po_number = m.group(1).strip()

    return vendor_name, amount, iban, po_number


fraud = []

with pdfplumber.open(INVOICES_PATH) as pdf:
    for idx, page in enumerate(pdf.pages, start=1):
        text = page.extract_text() or ''
        vendor_name, amount, iban, po_number = parse_invoice(text)

        vendor, _ = match_vendor(vendor_name)

        reason = None
        if vendor is None:
            reason = 'Unknown Vendor'
        else:
            invoice_iban = (iban or '').strip().upper().replace(' ', '')
            if invoice_iban != vendor['iban']:
                reason = 'IBAN Mismatch'
            else:
                if not po_number or po_number not in po_map:
                    reason = 'Invalid PO'
                else:
                    po = po_map[po_number]
                    if amount is None or abs(amount - po['amount']) > 0.01:
                        reason = 'Amount Mismatch'
                    else:
                        if po['vendor_id'] != vendor['id']:
                            reason = 'Vendor Mismatch'

        if reason:
            fraud.append({
                'invoice_page_number': idx,
                'vendor_name': vendor_name,
                'invoice_amount': round(amount, 2) if amount is not None else None,
                'iban': iban,
                'po_number': po_number if po_number else None,
                'reason': reason,
            })

with open(OUTPUT_PATH, 'w', encoding='utf-8') as f:
    json.dump(fraud, f, indent=2)

print('flagged', len(fraud))
print('wrote', OUTPUT_PATH)
PY"}
